cypress_script:
describe('Login Functionality', () => {
  it('should successfully log in with valid credentials', () => {
    cy.visit('https://automationexercise.com/login');
    cy.get('input[name="email"]').type('validemail@example.com');
    cy.get('input[name="password"]').type('validpassword');
    cy.get('button.btn.btn-default').contains('Login').click();
    cy.url().should('eq', 'https://automationexercise.com/');
  });
  it('should show an error for invalid credentials', () => {
    cy.visit('https://automationexercise.com/login');
    cy.get('input[name="email"]').type('invalidemail@example.com');
    cy.get('input[name="password"]').type('invalidpassword');
    cy.get('button.btn.btn-default').contains('Login').click();
    cy.url().should('eq', 'https://automationexercise.com/login');
  });
});

playwright_script:
import { test } from '@playwright/test';

test.describe('Login Functionality', () => {
  test('should successfully log in with valid credentials', async ({ page }) => {
    await page.goto('https://automationexercise.com/login');
    await page.fill('input[name="email"]', 'validemail@example.com');
    await page.fill('input[name="password"]', 'validpassword');
    await page.click('button.btn.btn-default:has-text("Login")');
    await page.waitForURL('https://automationexercise.com/');
  });
  test('should show an error for invalid credentials', async ({ page }) => {
    await page.goto('https://automationexercise.com/login');
    await page.fill('input[name="email"]', 'invalidemail@example.com');
    await page.fill('input[name="password"]', 'invalidpassword');
    await page.click('button.btn.btn-default:has-text("Login")');
    await page.waitForURL('https://automationexercise.com/login');
  });
});
